            new[] { "settings.row.musicFolder", "", "Custom music folder", "Folder/URL with a manifest.json mapping combat/boss/shop/rest/… to track files. Empty = the score shipped in music/ beside the game, or the built-in generated score where that is unavailable.", "" },
            new[] { "settings.row.musicFolder.placeholder", "", "e.g. music/ or https://…", "", "" },
            new[] { "settings.row.touchFlickPlay", "", "Card flick to play", "Flick a card upward with touch, mouse, trackpad or pen to play it on the nearest valid target. Selection and the information button work as usual.", "" },
            new[] { "settings.row.touchFlickDistance", "", "Card flick distance", "Upward travel in screen pixels. Shorter needs less movement; longer helps avoid accidental plays. Release with an upward flick.", "" },
            new[] { "tutorial.playCards.tap", "", "Tap a card to play it; with several enemies, tap the one to hit. You can also press 1–9, or drag the card onto an enemy.", "", "" },
            new[] { "tutorial.playCards.select", "", "Click a card or press 1–9 to select it; click it again to play it. Attacks need a target — click an enemy or drag the card onto it.", "", "" },
            new[] { "settings.row.oneTapPlay", "", "Tap a card to play it", "Off (the default): a tap selects the card, and the next tap on it, or picking a target, plays it. This holds in solo and in co-op. On: one tap plays a card when there is only one possible target: a self card, an all-enemy card, or one living enemy. With several enemies a tap still selects. Holding a card selects it without playing, which shows its details and Upcast.", "" },
            new[] { "settings.row.reducedMotion", "", "Reduced motion", "Calm ambient effects, drop the map pulse, and shorten animations.", "" },
            new[] { "settings.row.highContrast", "", "High contrast", "Brighter text and stronger borders throughout for readability. On by default — turn it off for the dimmer, more atmospheric palette.", "" },
            new[] { "settings.row.textSize", "", "Text size", "Scale interface text from the browser baseline. Auto follows the browser stylesheet; S/L/XL aid readability. Stacks with UI size.", "" },
            new[] { "settings.row.tapFloor", "", "Minimum tap size", "How small a button, tab, or option is allowed to get. 44 is the size a fingertip reliably hits; smaller fits more on screen.", "" },
            new[] { "settings.row.colorblindSafe", "", "Colorblind-friendly", "Shift danger/heal/blight/frost colors to a more distinguishable palette.", "" },
            new[] { "settings.row.reduceFlashes", "", "Reduce flashes", "Suppress bright impact and proc flashes (photosensitivity). Damage numbers stay.", "" },
            new[] { "settings.row.readableHeadings", "", "Readable headings", "Use the plain UI font for titles instead of the decorative serif.", "" },
            new[] { "settings.row.commandLog", "", "Command log", "The recent commands and results between the interface and the engine. Copy it into a bug report if the game misbehaves.", "" },
            new[] { "settings.row.debugMode", "", "Debug mode", "Shows a Console button during combat and in the combat log, with errors and every ignored tap, so a stuck turn can be copied or exported.", "" },
            new[] { "settings.row.shopSell", "", "Merchant buys back", "The shop offers a Sell bar for relics and flasks, at his prices. Off removes the bar entirely.", "" },
            new[] { "settings.row.holdConfirm", "", "Hold to confirm", "Choices a run can’t take back fill as you hold them, so a mis-tap can be let go before it lands. Off returns to one tap.", "" },
            new[] { "settings.row.rewardCollect", "", "Reward collection", "Auto: Continue takes everything you didn’t skip, picking a card for you. Manual: Continue means done — only what you chose comes along.", "" },
            new[] { "settings.row.swapCostRule", "", "Weapon swap cost", "What switching armament sets costs mid-fight. FLAT charges the same for every weapon; TALISMAN & RELIC starts there and lets your gear make it dearer or cheaper; WEAPON CATEGORY prices it by the weapon you are drawing — a heavy one is slow, a quick one is not. Takes effect on the next fight.", "" },
            new[] { "settings.row.cardWidth_glance", "", "Resting card width", "How wide a card is while you are browsing past it, in pixels. Must stay smaller than the selected width.", "" },
            new[] { "settings.row.cardWidth_glance_mobile", "", "Resting card width, phone", "The resting width on a narrow screen. It ships equal to the resting width above, so nothing changes until you move it.", "" },
            new[] { "settings.row.cardWidth_focus", "", "Selected card width", "How wide the card you have picked out becomes. Must sit between the resting and reading widths.", "" },
            new[] { "settings.row.cardWidth_inspect", "", "Reading card width", "How wide a card is in the window you open to read it. Must stay larger than the selected width.", "" },
            new[] { "settings.row.cardSizeExport", "", "Export card sizes", "Copies the tuned sizes as a JSON fragment shaped like content/config/ui/components/card.json itself — merge it in at the FILE ROOT, where it replaces sizing.levels. It carries only the widths, so ratio, bands and behavior are left alone.", "" },
            new[] { "settings.row.levelUpValue", "", "Level-up value", "How many stat points one level grants — type any whole number from 1 to 20. Takes effect on the next level you reach, in any run, including one already in progress; the points wait at the shrine until you assign them.", "" },
            new[] { "settings.row.deckEditing", "", "Deck editing", "Add, remove and arrange your cards between fights. Off: the deck changes only through rewards, the merchant and the Armoury.", "" },
            new[] { "settings.row.deckEditingWhere", "", "Where you can edit", "Free opens the editor from the Armoury at any moment out of combat. Rest sites only offers it at a Shrine, an inn or a chapel.", "" },
            new[] { "settings.row.deckMinUnlimited", "", "No minimum deck size", "Let the editor confirm a deck of any size, however small.", "" },
            new[] { "settings.row.deckMinSize", "", "Minimum deck size", "The fewest cards the editor lets you confirm. Rewards and purchases can still move the deck outside it; the editor then asks you to bring it back.", "" },
            new[] { "settings.row.deckMaxUnlimited", "", "No maximum deck size", "Let the editor confirm a deck of any size, however large.", "" },
            new[] { "settings.row.deckMaxSize", "", "Maximum deck size", "The most cards the editor lets you confirm. It may not sit below the minimum.", "" },
            new[] { "settings.row.classSpellPowerCopies", "", "Copies of a class spell or Power", "How many copies of one of your class’s own spells or Powers the editor lets your deck hold. Strike and Defend stay unlimited; weapon arts and techniques stay limited to the copies you own.", "" },
            new[] { "settings.row.playInDeckOrder", "", "Play in deck order", "Your draw pile is not shuffled: you draw your cards in the order you arranged them, and a spent pile returns in that order. Card effects that shuffle still shuffle. Applies from the next fight.", "" },
            new[] { "settings.row.combatRoundsPreview", "", "Combat rounds preview", "Runs real fights on the speed-ordered combat rounds preview. Off by default. Read at New Run and fixed for that run; a fight already under way keeps the rules it started with. Dev and test builds only.", "" },
            new[] { "settings.row.promptSettingsExport", "", "Offer export when done", "Ask to export a configuration file after Done and Save.", "" },
            new[] { "settings.row.gameConfigExport", "", "Export game configuration", "Save every non-default game configuration value. Desktop opens Save As when available; mobile downloads the JSON locally.", "" },
            new[] { "settings.row.gameConfigImport", "", "Load game configuration", "Choose an exported settings JSON file. Included values replace your current settings; other settings and saved runs are untouched. Presentation changes apply immediately; starting stats and balance apply to new runs.", "" },
            new[] { "settings.group.Opening", "", "Opening sequence", "Opening artwork, dialogue, timing, motif and preview. Included in configuration exports.", "" },
            new[] { "settings.group.Progression", "", "Character & progression", "Creation points, each class’s defaults, level-up, experience, skills and talents. What the points turn into is under Stats.", "" },
            new[] { "settings.group.Combat", "", "Combat rules", "Action and resource costs, card values, deck limits and arcane exposure. Combat pacing, animation, sprites and Armaments are in General → Combat.", "" },
            new[] { "settings.group.Stats", "", "Stats", "Everything that turns attributes into Draw and hand size, HP, Stamina, Mana, Poise, Ward and the combat ratings — one topic per trait, each with a live worked example.", "" },
            new[] { "settings.group.Recovery", "", "Recovery", "How HP, Stamina and Mana come back: each turn, after going unused for a few turns, every few rounds, after a won fight, and at every Rest. Applies from the next fight.", "" },
            new[] { "settings.group.Rewards", "", "Rewards & economy", "Cinders, reward rarity, merchants, flasks and smithing.", "" },
            new[] { "settings.group.Deck", "", "Deck", "The deck editor: where you can edit, the deck’s size limits, and playing your cards in the order you arranged them.", "" },
            new[] { "settings.group.Equipment", "", "Equipment & relics", "Starting kits, drops, swapping, equipment balance and relic values.", "" },
