            new[] { "settings.row.wireframeModalWidth", "", "Modal window width", "A window opens at the narrowest of four widths that holds what is in it. This moves every window one step along that ladder — narrower to see more of the game behind it, wider for fewer wrapped lines. Windows already open change with it, and a window at either end of the ladder stays there.", "" },
            new[] { "settings.row.wireframeModalFooter", "", "Modal footer buttons", "How far the buttons along the bottom of a window run: Short is about a third of a wide window, Long about two thirds, and Full width gives them the whole footer — which is what a phone already does. Each window picks its own today; this asks every one of them for the same.", "" },
            new[] { "settings.row.wireframeMenuNav", "", "Category navigation", "Every menu with categories — Shop, Armoury, Compendium, Profile, character creation — lists them down the left when they fit and folds them into one [Category ▾] button above the page when they do not. Rail and Selector answer for the screen instead, on every menu, including a narrow one that would not have chosen the list itself.", "" },
            new[] { "settings.row.wireframeMenuFrame", "", "Workspace frame", "How much of the screen a workspace menu takes — the Compendium, your Profile, the Smith and the stable. Fill the screen removes the margin around it; Inset pulls it in. Menus already open change with it.", "" },
            new[] { "settings.row.wireframeSceneSkyline", "", "Scene backdrop", "The painted place behind a fight or a conversation (the drawings call it WGS6). Never drawn leaves the scene on its plain background, which is the least a scene can draw. A fight or a conversation on screen takes it at once.", "" },
            new[] { "settings.row.wireframeSceneFloor", "", "Scene ground line", "How the painting is cropped to the ground band at the bottom of a scene (the drawings call it WGS7). Aligned puts its painted ground line exactly on that band; the plain crop centres the painting instead. Where the fighters stand is set by the formation and does not move either way.", "" },
